ball = sphere(pos=vec(40, 40, 0))
ball.v = vec(0, 1, 0)
gameOverBool = False
grounds = []
grounds.append(box(pos=vec(40, 30, 0), size=vec(20, 2, 10)))#오른쪽 위(스폰)
grounds.append(box(pos=vec(15, 26, 0), size=vec(10, 2, 10)))#오른쪽 위(두 번째)
grounds.append(box(pos=vec(-20, 26, 0), size=vec(20, 2, 10)))
grounds.append(box(pos=vec(55, -20, 0), size=vec(10, 2, 10)))
grounds.append(box(pos=vec(-60, -12, 0), size=vec(20, 2, 10)))
dangers = []
dangers.append(box(pos=vec(30, 28, 0), size=vec(20, 2, 10), color=vec(1, 0, 0)))
dangers.append(box(pos=vec(60, 30, 0), size=vec(20, 2, 10), color=vec(1, 0, 0)))
dangers.append(box(pos=vec(-50, 26, 0), size=vec(30, 2, 10), color=vec(1, 0, 0)))
breakables = []
for i in range(4):
    breakables.append(box(pos=vec(-6, 24-i*7, 0), size=vec(6, 6, 10), textures=textures.rough, color=vec(1, 1, 0)))
for i in range(4):
    breakables.append(box(pos=vec(1, 24-i*7, 0), size=vec(6, 6, 10), textures=textures.rough, color=vec(1, 1, 0)))
movingBlocks = []
for i in range(10):
    movingBlocks.append(box(pos=vec(-20+i*7, -20, 0), size=vec(6, 6, 10), color=color.cyan))
    movingBlocks[i].visible = False
movingNum = 0
stars = []
stars.append(sphere(pos=vec(-25, 30, 0), color=vec(1, 1, 0), emissive=True))
stars.append(sphere(pos=vec(55, -16, 0), color=vec(1, 1, 0), emmissive=True))
stars.append(sphere(pos=vec(-60, -8, 0), color=vec(1, 1, 0), emmissive=True))
starsNum = len(stars)
throwingObject = box(pos=vec(70, -10, 0), size=vec(10, 10, 10), color=vec(0, 0, 1))


def freeFall():
    ball.pos.y -= 0.05 * ball.v.y
    ball.v.y += 0.005 * 9.8


def movement():
    ev = keysdown()
    if 'left' in ev:
        ball.pos.x -= 0.15
    elif 'right' in ev:
        ball.pos.x += 0.15


def gameOver():
    global ball
    global gameOverBool
    ball.visible = False
    del ball
    gameOverBool = True


while True:
    rate(150)
    freeFall()
    movement()
    movingNum += 1

    for i in range(len(grounds)):
        if (ball.pos.x >= (grounds[i].pos.x-grounds[i].size.x/2)) and (ball.pos.x <= (grounds[i].pos.x+grounds[i].size.x/2)):
            if abs((ball.pos.y - grounds[i].pos.y)) <= (grounds[i].size.y/2+1):
                ball.v.y = -4
                break

    for i in range(len(breakables)):
        if (ball.pos.x >= (breakables[i].pos.x-breakables[i].size.x/2)) and (ball.pos.x <= (breakables[i].pos.x+breakables[i].size.x/2)):
            if abs((ball.pos.y - breakables[i].pos.y)) <= (breakables[i].size.y/2+2):
                ball.v.y = -4
                breakables[i].visible = False
                del breakables[i]
                break

    for i in range(len(stars)):
        if ((ball.pos.x-stars[i].pos.x)**2 + (ball.pos.y-stars[i].pos.y)**2) <= 4:
            stars[i].visible = False

    for i in range(len(movingBlocks)):
        if movingNum == 600:#optimize
            movingNum = 0
        if movingNum % 600 == 60*i:
            movingBlocks[i].visible = True
        elif movingNum % 600 == (300+60*i) % 600:
            movingBlocks[i].visible = False
        if movingBlocks[i].visible:
            if (ball.pos.x >= (movingBlocks[i].pos.x-movingBlocks[i].size.x/2)) and (ball.pos.x <= (movingBlocks[i].pos.x+movingBlocks[i].size.x/2)):
                if abs((ball.pos.y - movingBlocks[i].pos.y)) <= (movingBlocks[i].size.y/2+2):
                    ball.v.y = -4

    if ball.pos.y <= -100:
        print("game over")
        break

    if (ball.pos.x >= (throwingObject.pos.x-throwingObject.size.x/2)) and (ball.pos.x <= (throwingObject.pos.x+throwingObject.size.x/2)):
        if abs((ball.pos.y - throwingObject.pos.y)) <= (throwingObject.size.y/2+2):
            ball.pos = vec(70, -10, 0)
            while True:
                rate(150)
                ball.pos.x -= 0.3
                k = keysdown()
                if ('left' in k) or ('right' in k):
                    break

    for i in range(len(dangers)):
        if (ball.pos.x >= (dangers[i].pos.x-dangers[i].size.x/2)) and (ball.pos.x <= (dangers[i].pos.x+dangers[i].size.x/2)):
            if abs((ball.pos.y - dangers[i].pos.y)) <= (dangers[i].size.y/2+2):
                gameOver()
                break

    if gameOverBool:
        print("game over")
        break

    if (not stars[0].visible) and (not stars[1].visible) and (not stars[2].visible):
        print("clear")
        break

